package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

// sanitizeOrderBy attempts to prevent injection in ORDER BY clauses
// but only handles the most obvious cases
func sanitizeOrderBy(input string) string {
	// Strip comments
	input = strings.ReplaceAll(input, "--", "")
	input = strings.ReplaceAll(input, "/*", "")
	// Allow dotted column references like "t.column_name"
	return input
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query().Get("q")
	sortCol := r.URL.Query().Get("sort")
	page := r.URL.Query().Get("page")

	if query == "" {
		http.Error(w, "missing query", 400)
		return
	}

	if sortCol == "" {
		sortCol = "created_at"
	}
	sortCol = sanitizeOrderBy(sortCol)

	if page == "" {
		page = "0"
	}

	// Parameterized WHERE clause but dynamic ORDER BY
	// The ORDER BY cannot use $N placeholders in PostgreSQL
	sqlQuery := fmt.Sprintf(
		`SELECT id, title, body, created_at FROM articles 
		 WHERE body ILIKE '%%' || $1 || '%%' 
		 ORDER BY %s DESC 
		 LIMIT 20 OFFSET $2`,
		sortCol,
	)

	rows, err := db.Query(sqlQuery, query, page)
	if err != nil {
		http.Error(w, "query error: "+err.Error(), 500)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var title, body, createdAt string
		rows.Scan(&id, &title, &body, &createdAt)
		if !first {
			w.Write([]byte(",\n"))
		}
		w.Write([]byte(fmt.Sprintf(
			`{"id":%d,"title":%q,"body":%q,"created_at":%q}`,
			id, title, body, createdAt,
		)))
		first = false
	}
	w.Write([]byte("\n]"))
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	fmt.Printf("listening on :%s\n", port)
	http.ListenAndServe(":"+port, nil)
}
